sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var requestBody = request.body.data;

    if (!requestBody || !requestBody.first_name || !requestBody.last_name || !requestBody.email || !requestBody.contact_number || !requestBody.event_id) {
        return response.setStatus(400).setBody({ error: "Missing required fields" });
    }

    var _attendeeGR = new GlideRecordSecure('x_1610434_event_0_attendee');
    _attendeeGR.initialize();
    _attendeeGR.setValue('first_name', requestBody.first_name);
    _attendeeGR.setValue('last_name', requestBody.last_name);
    _attendeeGR.setValue('email', requestBody.email);
    _attendeeGR.setValue('contact_number', requestBody.contact_number);
	if (requestBody.event_id) {
        var _eventGR = new GlideRecordSecure('x_1610434_event_0_event_record');
		_eventGR.addQuery('number', requestBody.event_id);
		_eventGR.query();
        if (_eventGR.next()) {
            _attendeeGR.setValue('event_id', _eventGR.getUniqueValue());
        } else {
            response.setStatus(404);
            return response.setBody({ error: "Provided Event not found" });
        }
    }
    _attendeeGR.insert();

    response.setStatus(201);
    response.setBody({
        message: "Attendee created successfully",
        attendeeId: _attendeeGR.getUniqueValue()
    });
})(request, response);
